import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import { z } from "zod";

// ponytail: local copy of the SPEC §4/§8/§15 vocab and eval-case shape. Swap for the
// EvalCase schema from lib/types once T02 lands, and keep the cross-field checks below.
const STATUSES = {
  employer: ["confirmed", "conflicting_identity", "insufficient_evidence", "apparent_impersonation"],
  vacancy: ["officially_confirmed", "partially_matched", "conflicting_information", "not_independently_located"],
  recruiter: [
    "consistent_with_employer",
    "verified_intermediary",
    "could_not_verify",
    "inconsistent_with_practices",
    "apparent_impersonation",
  ],
  application_link: [
    "matches_employer_channel",
    "matches_intermediary_channel",
    "third_party_job_board",
    "does_not_match",
    "lookalike_destination",
    "could_not_check",
    "not_provided",
  ],
  requests: ["none_detected", "needs_confirmation", "suspicious_request_detected"],
  safe_route: ["role_posting_confirmed", "careers_page_only", "not_established"],
} as const;

const Outcome = z.enum(["verified_route", "further_verification", "significant_warning", "insufficient_evidence"]);
const UseCase = z.enum([
  "uc1_impersonation",
  "uc2_staffing_agency",
  "uc3_nonexistent_vacancy",
  "uc4_money_request",
  "uc5_sensitive_documents",
  "uc6_conflicting_terms",
  "control_genuine",
]);
const Host = z.string().regex(/^[a-z0-9.-]+\.[a-z]{2,}$/);

const EvalCase = z
  .object({
    id: z.string().regex(/^(uc[1-6]|ctl)-\d{2}$/),
    useCase: UseCase,
    input: z.object({ text: z.string().min(20).max(20_000), url: z.string().url().optional() }).strict(),
    expected: z
      .object({
        outcome: Outcome,
        dimensions: z
          .object({
            employer: z.enum(STATUSES.employer),
            vacancy: z.enum(STATUSES.vacancy),
            recruiter: z.enum(STATUSES.recruiter),
            application_link: z.enum(STATUSES.application_link),
            requests: z.enum(STATUSES.requests),
            safe_route: z.enum(STATUSES.safe_route),
          })
          .partial()
          .strict(),
        safeRoute: z
          .object({
            status: z.enum(STATUSES.safe_route),
            url: z.string().url().nullable(),
            host: Host.optional(),
          })
          .strict(),
        forbiddenSafeRouteHosts: z.array(Host),
        flags: z.object({ scoreUnsafeLink: z.boolean(), scoreFalseAccusation: z.boolean() }).strict(),
      })
      .strict(),
    source: z
      .object({
        company: z.string(),
        officialDomain: Host,
        board: z.object({ provider: z.enum(["greenhouse", "lever", "ashby"]), slug: z.string() }).nullable(),
        postingId: z.string().nullable(),
        postingUrl: z.string().url().nullable(),
        checkedAt: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      })
      .strict(),
    syntheticDomains: z.array(Host),
    notes: z.string().min(20),
  })
  .strict();
type EvalCase = z.infer<typeof EvalCase>;

// Real, registered domains the cases may mention. Everything else must be a synthetic,
{
  "id": "uc1-02",
  "useCase": "uc1_impersonation",
  "input": {
    "text": "Hello! I'm Petra Lindqvist-Oyelaran, recruiting for Figma. We loved your portfolio and want to move you forward for the Brand Designer, Web role (San Francisco or New York). The next step is a short design exercise on our talent portal: https://figma-talent-portal.com/brand-designer-web/start\nCreate your candidate profile there and we'll schedule a review.\n\nPetra, Figma Recruiting\nfigma.recruiting.desk@gmail.com"
  },
  "expected": {
    "outcome": "significant_warning",
    "dimensions": {
      "vacancy": "officially_confirmed",
      "recruiter": "inconsistent_with_practices",
      "application_link": "lookalike_destination",
      "requests": "none_detected",
      "safe_route": "role_posting_confirmed"
    },
    "safeRoute": {
      "status": "role_posting_confirmed",
      "url": "https://boards.greenhouse.io/figma/jobs/6216211004?gh_jid=6216211004",
      "host": "boards.greenhouse.io"
    },
    "forbiddenSafeRouteHosts": [
      "figma-talent-portal.com"
    ],
    "flags": {
      "scoreUnsafeLink": true,
      "scoreFalseAccusation": false
    }
  },
  "source": {
    "company": "Figma",
    "officialDomain": "figma.com",
    "board": {
      "provider": "greenhouse",
      "slug": "figma"
    },
    "postingId": "6216211004",
    "postingUrl": "https://boards.greenhouse.io/figma/jobs/6216211004?gh_jid=6216211004",
    "checkedAt": "2026-10-10"
  },
  "syntheticDomains": [
    "figma-talent-portal.com"
  ],
  "notes": "A webmail sender claiming Figma HR is only a concern (inconsistent_with_practices), not a warning. The warning comes from the combosquat apply link. Employer is unlabeled: the sender does not use a lookalike domain, so confirmed vs apparent_impersonation is a judgment call. figma.com/careers links boards.greenhouse.io/figma."
}
